// -----------------------------------------------------------------------------
// ImDrawList
// -----------------------------------------------------------------------------
ImDrawList::ImDrawList() {
    VtxBuffer = nullptr;
    VtxBufferSize = 0;
    VtxCount = 0;
    IdxBuffer = nullptr;
    IdxBufferSize = 0;
    IdxCount = 0;
    CmdBuffer = nullptr;
    CmdBufferSize = 0;
    CmdCount = 0;
}

ImDrawList::~ImDrawList() {
    if (VtxBuffer) free(VtxBuffer);
    if (IdxBuffer) free(IdxBuffer);
    if (CmdBuffer) free(CmdBuffer);
}

void ImDrawList::Clear() {
    VtxCount = 0;
    IdxCount = 0;
    CmdCount = 0;
}

void ImDrawList::Reserve(int vtx_count, int idx_count) {
    if (VtxCount + vtx_count > VtxBufferSize) {
        int new_cap = (VtxCount + vtx_count < 1024) ? 1024 : (VtxCount + vtx_count) * 2;
        VtxBuffer = (ImDrawVert*)realloc(VtxBuffer, new_cap * sizeof(ImDrawVert));
        VtxBufferSize = new_cap;
    }
    if (IdxCount + idx_count > IdxBufferSize) {
        int new_cap = (IdxCount + idx_count < 2048) ? 2048 : (IdxCount + idx_count) * 2;
        IdxBuffer = (unsigned short*)realloc(IdxBuffer, new_cap * sizeof(unsigned short));
        IdxBufferSize = new_cap;
    }
}

void ImDrawList::AddDrawCmd() {
    if (CmdCount > 0 && CmdBuffer[CmdCount - 1].ElemCount == 0) return;
    if (CmdCount >= CmdBufferSize) {
        int new_cap = (CmdBufferSize == 0) ? 16 : CmdBufferSize * 2;
        CmdBuffer = (ImDrawCmd*)realloc(CmdBuffer, new_cap * sizeof(ImDrawCmd));
        CmdBufferSize = new_cap;
    }
    ImDrawCmd& cmd = CmdBuffer[CmdCount++];
    cmd.ClipRectX = 0;
    cmd.ClipRectY = 0;
    cmd.ClipRectW = 8192;
    cmd.ClipRectH = 8192;
    cmd.ElemCount = 0;
    cmd.TextureId = nullptr;
}

void ImDrawList::AddLine(const ImVec2& p1, const ImVec2& p2, ImU32 col, float thickness) {
    float dx = p2.x - p1.x;
    float dy = p2.y - p1.y;
    float len = dx * dx + dy * dy;
    if (len <= 0.0f) return;
    float inv_len = 1.0f / sqrtf(len);
    dx *= inv_len;
    dy *= inv_len;
    float nx = -dy * (thickness * 0.5f);
    float ny = dx * (thickness * 0.5f);

    Reserve(4, 6);
    if (CmdCount == 0) AddDrawCmd();

    unsigned short idx0 = (unsigned short)VtxCount;
    ImDrawVert* v = &VtxBuffer[VtxCount];
    v[0].pos = ImVec2(p1.x + nx, p1.y + ny); v[0].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[0].col = col;
    v[1].pos = ImVec2(p2.x + nx, p2.y + ny); v[1].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[1].col = col;
    v[2].pos = ImVec2(p2.x - nx, p2.y - ny); v[2].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[2].col = col;
    v[3].pos = ImVec2(p1.x - nx, p1.y - ny); v[3].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[3].col = col;
    VtxCount += 4;

    unsigned short* idx = &IdxBuffer[IdxCount];
    idx[0] = idx0; idx[1] = idx0 + 1; idx[2] = idx0 + 2;
    idx[3] = idx0; idx[4] = idx0 + 2; idx[5] = idx0 + 3;
    IdxCount += 6;
    CmdBuffer[CmdCount - 1].ElemCount += 6;
}

void ImDrawList::AddRect(const ImVec2& p_min, const ImVec2& p_max, ImU32 col, float rounding, float thickness) {
    (void)rounding;
    AddLine(ImVec2(p_min.x, p_min.y), ImVec2(p_max.x, p_min.y), col, thickness);
    AddLine(ImVec2(p_max.x, p_min.y), ImVec2(p_max.x, p_max.y), col, thickness);
    AddLine(ImVec2(p_max.x, p_max.y), ImVec2(p_min.x, p_max.y), col, thickness);
    AddLine(ImVec2(p_min.x, p_max.y), ImVec2(p_min.x, p_min.y), col, thickness);
}

void ImDrawList::AddRectFilled(const ImVec2& p_min, const ImVec2& p_max, ImU32 col, float rounding) {
    (void)rounding;
    Reserve(4, 6);
    if (CmdCount == 0) AddDrawCmd();

    unsigned short idx0 = (unsigned short)VtxCount;
    ImDrawVert* v = &VtxBuffer[VtxCount];
    v[0].pos = ImVec2(p_min.x, p_min.y); v[0].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[0].col = col;
    v[1].pos = ImVec2(p_max.x, p_min.y); v[1].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[1].col = col;
    v[2].pos = ImVec2(p_max.x, p_max.y); v[2].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[2].col = col;
    v[3].pos = ImVec2(p_min.x, p_max.y); v[3].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[3].col = col;
    VtxCount += 4;

    unsigned short* idx = &IdxBuffer[IdxCount];
    idx[0] = idx0; idx[1] = idx0 + 1; idx[2] = idx0 + 2;
    idx[3] = idx0; idx[4] = idx0 + 2; idx[5] = idx0 + 3;
    IdxCount += 6;
    CmdBuffer[CmdCount - 1].ElemCount += 6;
}

void ImDrawList::AddTriangle(const ImVec2& p1, const ImVec2& p2, const ImVec2& p3, ImU32 col, float thickness) {
    AddLine(p1, p2, col, thickness);
    AddLine(p2, p3, col, thickness);
    AddLine(p3, p1, col, thickness);
}

void ImDrawList::AddTriangleFilled(const ImVec2& p1, const ImVec2& p2, const ImVec2& p3, ImU32 col) {
    Reserve(3, 3);
    if (CmdCount == 0) AddDrawCmd();

    unsigned short idx0 = (unsigned short)VtxCount;
    ImDrawVert* v = &VtxBuffer[VtxCount];
    v[0].pos = p1; v[0].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[0].col = col;
    v[1].pos = p2; v[1].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[1].col = col;
    v[2].pos = p3; v[2].uv = ImVec2(WHITE_UV_U, WHITE_UV_V); v[2].col = col;
    VtxCount += 3;

    unsigned short* idx = &IdxBuffer[IdxCount];
    idx[0] = idx0; idx[1] = idx0 + 1; idx[2] = idx0 + 2;
    IdxCount += 3;
    CmdBuffer[CmdCount - 1].ElemCount += 3;
}

// -----------------------------------------------------------------------------
// ImFontAtlas
// -----------------------------------------------------------------------------
ImFontAtlas::ImFontAtlas() {
    TexID = nullptr;
    TexPixelsAlpha8 = nullptr;
    TexWidth = ATLAS_W;
    TexHeight = ATLAS_H;
}

ImFontAtlas::~ImFontAtlas() {
    ClearTexData();
}

void ImFontAtlas::ClearTexData() {
    if (TexPixelsAlpha8) {
        free(TexPixelsAlpha8);
        TexPixelsAlpha8 = nullptr;
    }
}

bool ImFontAtlas::GetTexDataAsRGBA32(unsigned char** out_pixels, int* out_width, int* out_height, int* out_bytes_per_pixel) {
    if (out_width) *out_width = ATLAS_W;
    if (out_height) *out_height = ATLAS_H;
    if (out_bytes_per_pixel) *out_bytes_per_pixel = 4;

    if (!TexPixelsAlpha8) {
        uint32_t* pixels = (uint32_t*)malloc(ATLAS_W * ATLAS_H * 4);
        for (int i = 0; i < ATLAS_W * ATLAS_H; i++) {
            pixels[i] = 0x00FFFFFF;
        }

        // Top-left 8x8 white pixel block
        for (int y = 0; y < 8; y++) {
            for (int x = 0; x < 8; x++) {
                pixels[y * ATLAS_W + x] = 0xFFFFFFFF;
            }
        }

        int curX = 12;
        int curY = 2;
        int rowH = 18;

        for (int c = 32; c < 127; c++) {
            int idx = c - 32;
            if (curX + 7 + 4 >= ATLAS_W) {
                curX = 12;
                curY += rowH;
            }

            for (int r = 0; r < 13; r++) {
                unsigned char rowBits = g_ProggyClean13[idx][r];
                for (int col = 0; col < 7; col++) {
                    if ((rowBits >> col) & 1) {
                        pixels[(curY + r) * ATLAS_W + (curX + col)] = 0xFFFFFFFF;
                    }
                }
            }

            g_Glyphs[c].u0 = (float)curX / (float)ATLAS_W;
            g_Glyphs[c].v0 = (float)curY / (float)ATLAS_H;
            g_Glyphs[c].u1 = (float)(curX + 7) / (float)ATLAS_W;
            g_Glyphs[c].v1 = (float)(curY + 13) / (float)ATLAS_H;
            g_Glyphs[c].w = 7;
            g_Glyphs[c].h = 13;

            curX += 11;
        }

        g_GlyphsInitialized = true;
        TexPixelsAlpha8 = (unsigned char*)pixels;
    }

    if (out_pixels) *out_pixels = TexPixelsAlpha8;
    return true;
}

void ImDrawList::AddText(const ImVec2& pos, ImU32 col, const char* text_begin, const char* text_end) {
    if (!text_begin) return;
    if (!g_GlyphsInitialized) {
        unsigned char* px = nullptr;
        ImGui::GetIO().Fonts->GetTexDataAsRGBA32(&px, nullptr, nullptr, nullptr);
    }

    float curX = pos.x;
    float curY = pos.y;
    const char* s = text_begin;

    while (*s && (!text_end || s < text_end)) {
        char ch = *s++;
        if (ch == '\n') {
            curX = pos.x;
            curY += 15.0f;
            continue;
        }
        if (ch < 32 || ch > 126) ch = '?';

        GlyphInfo& g = g_Glyphs[(unsigned char)ch];
        float x0 = curX;
        float y0 = curY;
        float x1 = curX + (float)g.w;
        float y1 = curY + (float)g.h;

        Reserve(4, 6);
        if (CmdCount == 0) AddDrawCmd();

        unsigned short idx0 = (unsigned short)VtxCount;
        ImDrawVert* v = &VtxBuffer[VtxCount];
        v[0].pos = ImVec2(x0, y0); v[0].uv = ImVec2(g.u0, g.v0); v[0].col = col;
        v[1].pos = ImVec2(x1, y0); v[1].uv = ImVec2(g.u1, g.v0); v[1].col = col;
        v[2].pos = ImVec2(x1, y1); v[2].uv = ImVec2(g.u1, g.v1); v[2].col = col;
        v[3].pos = ImVec2(x0, y1); v[3].uv = ImVec2(g.u0, g.v1); v[3].col = col;
        VtxCount += 4;

        unsigned short* idx = &IdxBuffer[IdxCount];
        idx[0] = idx0; idx[1] = idx0 + 1; idx[2] = idx0 + 2;
        idx[3] = idx0; idx[4] = idx0 + 2; idx[5] = idx0 + 3;
        IdxCount += 6;
        CmdBuffer[CmdCount - 1].ElemCount += 6;

        curX += 7.0f;
    }
}
